Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;
#define int long long
inline int read(){
    int k=1,x=0; char ch=getchar();
    do{
        if(ch=='-') k=-1;
        ch=getchar();
    }while(ch<'0'||ch>'9');
    while(ch>='0'&&ch<='9') x=x*10+(ch-'0'),ch=getchar();
    return k*x;
}
inline int cmin(int x,int y){return x<y?x:y;}
inline int cmax(int x,int y){return x>y?x:y;}
const int N=2e6+10,Mod=1e9+7,mod=998244353,B=1000000;
int n,idx,ans,sum[10];
vector<int> v[10];
int pow10[7]={1,10,100,1000,10000,100000,1000000};
inline int MOD(int x){return (x%mod+mod)%mod;}
inline void dfs1(int x,int len){
    ++idx; v[len].push_back(MOD(idx-x)); (sum[len]+=v[len].back())%=Mod;
    if(len==6) return;
    for(int i=0;i<10;i++) dfs1(x*10+i,len+1);
}
inline void dfs2(int x){
    if(x>n) return;
    if(x*B+(B-1)<=n && x*B*10>n){
        int now=idx;
        for(int i=6;i>=0;--i){
            int sz=v[i].size();
            int d=MOD(now-x*pow10[i]);
            int pos=lower_bound(v[i].begin(),v[i].end(),mod-d)-v[i].begin();
            ans=(ans+d*sz+sum[i]-mod*(sz-pos))%Mod;
            idx+=sz;
        }
        return;
    }
    idx++; ans=(ans+MOD(idx-x))%Mod;
    for(int i=0;i<10;i++) dfs2(x*10+i);
}
signed main(){
    n=read();
    dfs1(0,0);
    for(int i=0;i<=6;i++) sort(v[i].begin(),v[i].end());
    idx=0;
    for(int i=1;i<=9;i++) dfs2(i);
    printf("%lld",(ans+Mod)%Mod);
    return 0;
}
